  allow_shorts?: boolean;
  // Option instrument UUID from get_option_positions or get_option_instruments. The position must be type=long.
  option_id: string;
  // Number of contracts to exercise (positive integer, minimum 1).
  quantity: number;
  // Optional exercise reason: covering_early_assignment | buying_stocks | not_enough_liquidity_or_spread_too_wide | hedging_position.
  reason?: string;
  // Idempotency key (UUID). Generate once per logical exercise and re-send on retry. Omitting falls back to a server-generated key.
  ref_id?: string;
}): Promise<CallToolResult<{
  // Tool-specific result payload; see the inner properties for fields.
  data: {
  // The submitted exercise event.
  event: null | {
  // Brokerage account number. Mask all but the last 4 digits when displaying to the user.
  account_number: string;
  // Option chain UUID.
  chain_id: string;
  // ISO 8601 timestamp when the exercise request was created.
  created_at: string;
  // debit = call exercise (cash paid to acquire shares) | credit = put exercise (cash received for delivering shares).
  direction: string;
  // Settlement date of the exercise (YYYY-MM-DD).
  event_date: string;
  // Exercise event UUID.
  id: string;
  // Option instrument UUID.
  option_id: string;
  // Contracts exercised.
  quantity: string;
