  state: string;
  // Absolute cash amount of the exercise: strike × multiplier × contracts for calls; net proceeds for puts.
  total_cash_amount: string;
  // exercise (normal) | generic (index options in pending state — index options cannot be manually exercised).
  type: string;
  // Underlying spot price at exercise time. Nil when not yet available.
  underlying_price?: null | string;
