  // Corporate-action adjustment: 'none' (raw prices), 'split' (default), or 'all' (split + dividend; requires a day-or-coarser interval).
  adjustment_type?: string;
  // Session bounds. One of 'regular' (RTH, default) or 'extended'.
  bounds?: string;
  // End of the range (RFC3339 UTC). Optional — defaults to the current time when omitted.
  end_time?: string;
  // Fast EMA period. macd only (default 12).
  fast_period?: null | number;
  // Required bar interval the indicator is computed on. Intraday: 15second, 30second, minute, 5minute, 10minute, 30minute, hour, 4hour. Interday: day, week, month, 3month, 6month, year, 5year, 10year, 20year, 50year. The 1-minute bar is named 'minute' (not '1minute').
  interval: string;
  // Calculation method. pivot_points only; currently only 'classic'.
  method?: string;
  // Band/offset multiplier. keltner_channels (default 2) and supertrend (default 3) only.
  multiplier?: null | number;
  // Number of standard deviations for the bands. bollinger_bands only (default 2).
  num_std?: null | number;
  // How much of the series to return: 'series' (default, full range), 'latest' (most recent bar only), or 'last:N' (most recent N bars). The indicator is always computed over the full range first; this only trims the response.
  output?: string;
  // Lookback period in bars. Applies to ema, sma, rsi, momentum, roc, cci, williams_r, atr, mfi, adx, donchian_channels, bollinger_bands, keltner_channels, supertrend. Omit to use the indicator's default.
  period?: null | number;
  // Signal EMA period. macd only (default 9).
  signal_period?: null | number;
  // Slow EMA period. macd only (default 26).
  slow_period?: null | number;
  // Start of the range (RFC3339 UTC, e.g. '2026-01-01T00:00:00Z'). Required.
  start_time: string;
  // Stock symbol (uppercase). Exactly one symbol per call.
  symbol: string;
  // Indicator to compute. One of: ema, sma, rsi, momentum, roc, cci, williams_r, atr, mfi, adx, donchian_channels, bollinger_bands, macd, keltner_channels, supertrend, vwap, obv, pivot_points.
  type: string;
}): Promise<CallToolResult<{
