  // Session bounds echoed from the request.
  bounds: string;
  // Computed indicators. Exactly one entry (one indicator per request).
  indicators: null | Array<null | {
  // Numeric parameters actually used after defaults were applied, e.g. {"period":14} or {"fast_period":12,"slow_period":26,"signal_period":9}.
  params: { [key: string]: number; };
  // Output bars in ascending time order, after the warm-up region is dropped. Trimmed per the request's output mode (full series, the latest bar, or the last N).
  series: null | Array<null | {
  // Bar start timestamp (RFC3339 UTC), left-edge labeled.
