  // Total contracts available at ask_price.
  ask_size: number;
  // Highest current buy-side price. Zero when the book is closed or unavailable.
  bid_price: string;
  // Total contracts bid at bid_price.
  bid_size: number;
  // Underlying price at which the position breaks even at expiration (strike +/- premium).
  break_even_price: string;
  // Model probability the long side ends in profit at expiration, decimal.
  chance_of_profit_long: null | string;
  // Model probability the short side ends in profit at expiration, decimal.
  chance_of_profit_short: null | string;
  // Sensitivity of option price to a $1 move in the underlying.
  delta: null | string;
  // Rate of change of delta per $1 move in the underlying.
  gamma: null | string;
  // Upper bound of the likely fast-fill range for a buy.
  high_fill_rate_buy_price: string;
  // Upper bound of the likely fast-fill range for a sell.
  high_fill_rate_sell_price: string;
  // Market-implied future volatility, decimal (0.30 = 30%).
  implied_volatility: null | string;
  // UUID of the option contract; the canonical match key against closes[].instrument_id.
  instrument_id: string;
  // Lower bound of the likely fast-fill range for a buy.
  low_fill_rate_buy_price: string;
  // Lower bound of the likely fast-fill range for a sell.
  low_fill_rate_sell_price: string;
  // Mid-market fair value — canonical current price for valuation.
  mark_price: string;
  // Outstanding contracts not yet closed or expired.
  open_interest: number;
