};
  // Echoed request legs[] (option_id, side, position_effect, ratio_quantity per leg) so the response identifies which contract(s) were reviewed.
  legs: null | Array<{
  // Option instrument UUID (from get_option_instruments).
  option_id: string;
  // 'open' (new position) or 'close' (existing position). To close a long use sell; to close a short use buy.
  position_effect: string;
