  // Rate of change of delta per $1 move in the underlying.
  gamma: null | string;
  // Upper bound of the likely fast-fill range for a buy.
  high_fill_rate_buy_price: string;
  // Upper bound of the likely fast-fill range for a sell.
  high_fill_rate_sell_price: string;
