  // UUID of the option contract; the canonical match key against closes[].instrument_id.
  instrument_id: string;
  // Lower bound of the likely fast-fill range for a buy.
  low_fill_rate_buy_price: string;
  // Lower bound of the likely fast-fill range for a sell.
  low_fill_rate_sell_price: string;
  // Mid-market fair value — canonical current price for valuation.
  mark_price: string;
  // Outstanding contracts not yet closed or expired.
  open_interest: number;
  // YYYY-MM-DD trading date that previous_close_price corresponds to.
