  steps: Array<{
  action: "tap";
  // Runtime elementRef from the latest snapshot_ui or wait_for_ui output
  elementRef: string;
  // Seconds after this step. Omit for switch elementRefs.
  postDelay?: number;
  // Seconds before this step. Omit for switch elementRefs.
  preDelay?: number;
}>;
  waitTimeout?: number;
}): Promise<CallToolResult<unknown & unknown | unknown & unknown>>; };
```

